procedure SalonLateBalance {
  about "Remind late clients; escalate very late ones"
  policy SalonPolicy
  sheet Clients "Clients" { name: Text, phone: Phone, last_visit: Date, status: Text, tab: Money, color_formula: Text private }
  trigger every day at 10:00

  let all = fetch Clients
  let late = filter all where tab > $0.00 and days_between(last_visit, today()) > 3
