procedure DaycareWithdrawnFollowUp {
  about "Follow up with familys marked withdrawn"
  policy DaycarePolicy
  sheet Families "Families" { parent: Text, email: Email, due_date: Date, status: Text, balance: Money, health_notes: Text private }
  trigger every day at 17:30

  let all = fetch Families
  let recent = filter all where status == "withdrawn" and days_between(due_date, today()) <= 1 and days_between(due_date, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no withdrawn familys"
  }
  notify owner "Withdrawn familys to follow up: {n}"
  let msgs = draft each r in recent up to 20 email to r.email subject "Let's find a new time": "Hi {r.parent default 'there'}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
  for each r in recent up to 20 {
    update r set status = "contacted"
  }
}

