procedure ArcheryNoShowFollowUp {
  about "Follow up with archers marked no-show"
  policy ArcheryPolicy
  sheet LaneBookings "LaneBookings" { archer: Text, email: Email, lane_at: DateTime, status: Text, fee: Money, medical_info: Text private }
  trigger every day at 09:00

  let all = fetch LaneBookings
  let recent = filter all where status == "no-show" and days_between(lane_at, today()) <= 3 and days_between(lane_at, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show archers"
  }
  notify owner "No-show archers to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.archer}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
    update r set status = "contacted"
  }
}

