procedure FencingConfirmNewBout {
  about "Confirm a new bout and add it to the calendar"
  policy FencingPolicy
  sheet Fencers "Fencers" { fencer: Text, email: Email, bout_at: DateTime, status: Text, dues: Money, injury_notes: Text private }
  calendar Pistes "Pistes"
  trigger when new row r in Fencers

  if r.bout_at < now() + 12 hours {
    notify owner "Short-notice bout for {r.fencer} at {r.bout_at}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft email to r.email subject "Confirmed": "Hi {r.fencer default 'there'}, your bout with the club is confirmed for {r.bout_at}."
  let ok = request approval of m from owner timeout 1 day else stop "confirmation not approved"
  send ok
  let ev = book Pistes { title: "{r.fencer}", at: r.bout_at, length: 30 minutes }
  update r set status = "confirmed"
}

