procedure LandscapingLateBalance {
  about "Remind late customers; escalate very late ones"
  policy LandscapingPolicy
  sheet Quotes "Quotes" { customer: Text, email: Email, sent_on: Date, status: Text, amount: Money, gate_code: Text private }
  trigger every day at 08:30

  let all = fetch Quotes
  let late = filter all where amount > $0.00 and days_between(sent_on, today()) > 5
  for each r in late up to 30 {
    if days_between(r.sent_on, today()) > 14 {
      notify owner "{r.customer} is very late ({r.amount}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.customer}, our records show a amount of {r.amount}. Questions? Just reply."
      let ok = request approval of m from owner timeout 2 hours else skip
      send ok
    }
  }
}

