procedure PoolcleanOutreachCampaign {
  about "On request, contact recent cancelled owners"
  policy PoolcleanPolicy
  sheet Cleanings "Cleanings" { owner: Text, phone: Phone, clean_on: Date, status: Text, fee: Money, gate_code: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Cleanings
  let targets = filter all where status == "cancelled" and days_between(clean_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  let msgs = draft each r in targets up to 50 sms to r.phone: "Hi {r.owner}, come back to the service! Use code WELCOME10 on your next visit."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
}

