procedure JewelryCollectedFollowUp {
  about "Follow up with customers marked collected"
  policy JewelryPolicy
  sheet Tickets "Tickets" { customer: Text, phone: Phone, ready_on: Date, status: Text, quote: Money, insurance_value: Text private }
  trigger every wednesday at 11:00

  let all = fetch Tickets
  let recent = filter all where status == "collected" and days_between(ready_on, today()) <= 2 and days_between(ready_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
