    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.customer default 'there'}, our records show a prepaid of {r.prepaid}. Questions? Just reply."
      let ok = request approval of m from owner timeout 1 day else skip
      send ok
    }
  }
}

