procedure BookstoreLateBalance {
  about "Remind late customers; escalate very late ones"
  policy BookstorePolicy
  sheet Holds "Holds" { customer: Text, email: Email, held_until: Date, status: Text, prepaid: Money, phone_note: Text private }
  trigger every day at 08:00

  let all = fetch Holds
  let late = filter all where prepaid > $0.00 and days_between(held_until, today()) > 7
  for each r in late up to 40 {
    if days_between(r.held_until, today()) > 21 {
      notify owner "{r.customer} is very late ({r.prepaid}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.customer default 'there'}, our records show a prepaid of {r.prepaid}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
}

