procedure AquariumDelayedFollowUp {
  about "Follow up with customers marked delayed"
  policy AquariumPolicy
  sheet TankOrders "TankOrders" { customer: Text, phone: Phone, install_on: Date, status: Text, price: Money, home_access: Text private }
  trigger every day at 16:00

  let all = fetch TankOrders
  let recent = filter all where status == "delayed" and days_between(install_on, today()) <= 7 and days_between(install_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no delayed customers"
  }
  notify owner "Delayed customers to follow up: {n}"
  let msgs = draft each r in recent up to 30 sms to r.phone: "Hi {r.customer}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok
  for each r in recent up to 30 {
    update r set status = "contacted"
  }
}

