  let all = fetch Cleanings
  let recent = filter all where status == "skipped" and days_between(scheduled, today()) <= 1 and days_between(scheduled, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no skipped clients"
  }
  notify owner "Skipped clients to follow up: {n}"
  let msgs = draft each r in recent up to 20 sms to r.phone: "Hi {r.client default 'there'}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
  for each r in recent up to 20 {
