procedure BikeshopLateBalance {
  about "Remind late customers; escalate very late ones"
  policy BikeshopPolicy
  sheet Repairs "Repairs" { customer: Text, phone: Phone, ready_on: Date, status: Text, estimate: Money, lock_code: Text private }
  trigger every day at 09:00

  let all = fetch Repairs
  let late = filter all where estimate > $0.00 and days_between(ready_on, today()) > 5
  for each r in late up to 20 {
    if days_between(r.ready_on, today()) > 30 {
      notify owner "{r.customer} is very late ({r.estimate}). Please call."
    } else {
      let m = draft sms to r.phone: "Hello {r.customer}, our records show a estimate of {r.estimate}. Questions? Just reply."
      let ok = request approval of m from owner timeout 1 day else skip
      send ok
    }
  }
  notify owner "Please update my business partner yourself."
}

