procedure SignsLateBalance {
  about "Remind late clients; escalate very late ones"
  policy SignsPolicy
  sheet SignOrders "SignOrders" { client: Text, email: Email, due_on: Date, status: Text, quote: Money, proof_notes: Text private }
  trigger every day at 18:00

  let all = fetch SignOrders
  let late = filter all where quote > $0.00 and days_between(due_on, today()) > 7
  for each r in late up to 40 {
    if days_between(r.due_on, today()) > 21 {
