procedure StableNoShowFollowUp {
  about "Follow up with riders marked no-show"
  policy StablePolicy
  sheet Rides "Rides" { rider: Text, phone: Phone, ride_at: DateTime, status: Text, fee: Money, weight_notes: Text private }
  trigger every day at 10:00

  let all = fetch Rides
  let recent = filter all where status == "no-show" and days_between(ride_at, today()) <= 3 and days_between(ride_at, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show riders"
  }
  notify owner "No-show riders to follow up: {n}"
  for each r in recent up to 20 {
    let m = draft sms to r.phone: "Hi {r.rider default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "contacted"
  }
}

