procedure MusicMissedFollowUp {
  about "Follow up with students marked missed"
  policy MusicPolicy
  sheet Lessons "Lessons" { student: Text, parent_phone: Phone, lesson_at: DateTime, status: Text, balance: Money, progress_notes: Text private }
  trigger every friday at 18:00

  let all = fetch Lessons
  let recent = filter all where status == "missed" and days_between(lesson_at, today()) <= 3 and days_between(lesson_at, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no missed students"
  }
  notify owner "Missed students to follow up: {n}"
  let msgs = draft each r in recent up to 20 sms to r.parent_phone: "Hi {r.student}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
  for each r in recent up to 20 {
    update r set status = "contacted"
  }
}

