policy:
policy PoolcleanStockPolicy {
  allow read Chlorine(item, buckets, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Chlorine.supplier
  limit order $150 per action
  limit order $450 per day
}

program:
procedure PoolcleanReorder {
  about "Reorder supplies below their minimum"
  policy PoolcleanStockPolicy
  sheet Chlorine "Chlorine" { item: Text, buckets: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 17:30

  let all = fetch Chlorine
  let low = filter all where buckets < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $150.00 {
      notify owner "Reorder of {i.item} would cost {cost}, over the $150 limit."
      skip
    }
    order "{i.reorder_qty} x {i.item}" from i.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.item}"
  }
}

