procedure BikeshopWinBack {
  about "Nudge customers whose repair was long ago"
  policy BikeshopPolicy
  sheet Repairs "Repairs" { customer: Text, phone: Phone, ready_on: Date, status: Text, estimate: Money, lock_code: Text private }
  trigger every wednesday at 11:00

  let all = fetch Repairs
  let old = filter all where days_between(ready_on, today()) >= 60 and status != "cancelled"
  let oldest = sort old by ready_on first 15
  for each r in oldest up to 15 {
    let m = draft sms to r.phone: "Hi {r.customer}, it's been a while! We'd love to see you again at the shop."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

