procedure PetgroomerNoShowFollowUp {
  about "Follow up with pet owners marked no-show"
  policy PetgroomerPolicy
  sheet Grooms "Grooms" { owner: Text, phone: Phone, appointment: DateTime, status: Text, price: Money, behavior_notes: Text private }
  trigger every day at 09:00

  let all = fetch Grooms
  let recent = filter all where status == "no-show" and days_between(appointment, today()) <= 2 and days_between(appointment, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show pet owners"
