  notify owner "No-show pet owners to follow up: {n}"
  for each r in recent up to 40 {
    let m = draft sms to r.phone: "Hi {r.owner default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
    update r set status = "contacted"
  }
}

