procedure SignsDeliveredFollowUp {
  about "Follow up with clients marked delivered"
  policy SignsPolicy
  sheet SignOrders "SignOrders" { client: Text, email: Email, due_on: Date, status: Text, quote: Money, proof_notes: Text private }
  trigger every day at 11:00

  let all = fetch SignOrders
  let recent = filter all where status == "delivered" and days_between(due_on, today()) <= 1 and days_between(due_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no delivered clients"
  }
