  let msgs = draft each r in recent up to 20 email to r.email subject "Let's find a new time": "Hi {r.client}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
  for each r in recent up to 20 {
    update r set status = "contacted"
  }
}

