procedure BakeryReadyFollowUp {
  about "Follow up with customers marked ready"
  policy BakeryPolicy
  sheet CakeOrders "CakeOrders" { customer: Text, email: Email, pickup: Date, status: Text, price: Money, address: Text private }
  trigger every friday at 10:00

  let all = fetch CakeOrders
  let recent = filter all where status == "ready" and days_between(pickup, today()) <= 2 and days_between(pickup, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no ready customers"
  }
  notify owner "Ready customers to follow up: {n}"
  let msgs = draft each r in recent up to 30 email to r.email subject "Let's find a new time": "Hi {r.customer default 'there'}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
  for each r in recent up to 30 {
    update r set status = "contacted"
  }
}

