  allow supplier Chemicals.supplier
  limit order $200 per action
  limit order $600 per day
}

program:
procedure FilmlabReorder {
  about "Reorder chemicals below their minimum"
  policy FilmlabStockPolicy
  sheet Chemicals "Chemicals" { chemical: Text, litres: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 18:00

