  sheet Gymnasts "Gymnasts" { gymnast: Text, parent_email: Email, meet_on: Date, status: Text, fees: Money, medical_notes: Text private }
  trigger every day at 16:00

  let all = fetch Gymnasts
  let old = filter all where days_between(meet_on, today()) >= 60 and status != "left"
  let oldest = sort old by meet_on first 10
  for each r in oldest up to 10 {
    let m = draft email to r.parent_email subject "We miss you": "Hi {r.gymnast default 'there'}, it's been a while! We'd love to see you again at the club."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

