procedure SignsLateBalance {
  about "Remind late clients; escalate very late ones"
  policy SignsPolicy
  sheet SignOrders "SignOrders" { client: Text, email: Email, due_on: Date, status: Text, quote: Money, proof_notes: Text private }
  trigger every day at 08:30

  let all = fetch SignOrders
  let late = filter all where quote > $0.00 and days_between(due_on, today()) > 3
  for each r in late up to 20 {
    if days_between(r.due_on, today()) > 14 {
      notify owner "{r.client} is very late ({r.quote}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.client}, our records show a quote of {r.quote}. Questions? Just reply."
      let ok = request approval of m from owner timeout 1 day else skip
      send ok
    }
  }
}

