policy:
policy RestaurantStockPolicy {
  allow read Pantry(item, on_hand, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Pantry.supplier
  limit order $250 per action
  limit order $750 per day
}

program:
procedure RestaurantReorder {
  about "Reorder ingredients below their minimum"
  policy RestaurantStockPolicy
  sheet Pantry "Pantry" { item: Text, on_hand: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every monday at 09:00

  let all = fetch Pantry
  let low = filter all where on_hand < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $250.00 {
      notify owner "Reorder of {i.item} would cost {cost}, over the $250 limit."
      skip
    }
    order "{i.reorder_qty} x {i.item}" from i.supplier cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.item}"
  }
}

