procedure PrintshopLateBalance {
  about "Remind late customers; escalate very late ones"
  policy PrintshopPolicy
  sheet Jobs "Jobs" { customer: Text, email: Email, due: Date, status: Text, quote: Money, file_link: Text private }
  trigger every day at 10:00

  let all = fetch Jobs
  let late = filter all where quote > $0.00 and days_between(due, today()) > 5
  for each r in late up to 30 {
    if days_between(r.due, today()) > 14 {
      notify owner "{r.customer} is very late ({r.quote}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.customer}, our records show a quote of {r.quote}. Questions? Just reply."
      let ok = request approval of m from owner timeout 1 day else skip
      send ok
    }
  }
}

