procedure BikeshopLateBalance {
  about "Remind late customers; escalate very late ones"
  policy BikeshopPolicy
  sheet Repairs "Repairs" { customer: Text, phone: Phone, ready_on: Date, status: Text, estimate: Money, lock_code: Text private }
  trigger every friday at 18:00

  let all = fetch Repairs
  let late = filter all where estimate > $0.00 and days_between(ready_on, today()) > 7
  for each r in late up to 30 {
    if days_between(r.ready_on, today()) > 21 {
      notify owner "{r.customer} is very late ({r.estimate}). Please call."
    } else {
      let m = draft sms to r.phone: "Hello {r.customer default 'there'}, our records show a estimate of {r.estimate}. Questions? Just reply."
      let ok = request approval of m from owner timeout 6 hours else skip
      send ok
    }
  }
}

