procedure StableConfirmNewTrailRide {
  about "Confirm a new trail ride and add it to the calendar"
  policy StablePolicy
  sheet Rides "Rides" { rider: Text, phone: Phone, ride_at: DateTime, status: Text, fee: Money, weight_notes: Text private }
  calendar Arena "Arena"
  trigger when new row r in Rides

  if r.ride_at < now() + 12 hours {
    notify owner "Short-notice trail ride for {r.rider} at {r.ride_at}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.phone: "Hi {r.rider default 'there'}, your trail ride with the stable is confirmed for {r.ride_at}."
  let ok = request approval of m from owner timeout 1 day else stop "confirmation not approved"
  send ok
  let ev = book Arena { title: "{r.rider}", at: r.ride_at, length: 60 minutes }
  update r set status = "confirmed"
}

