procedure GymnasticsLateBalance {
  about "Remind late gymnasts; escalate very late ones"
  policy GymnasticsPolicy
  sheet Gymnasts "Gymnasts" { gymnast: Text, parent_email: Email, meet_on: Date, status: Text, fees: Money, medical_notes: Text private }
  trigger every wednesday at 10:00

  let all = fetch Gymnasts
  let late = filter all where fees > $0.00 and days_between(meet_on, today()) > 3
  for each r in late up to 30 {
    if days_between(r.meet_on, today()) > 14 {
      notify owner "{r.gymnast} is very late ({r.fees}). Please call."
    } else {
      let m = draft email to r.parent_email subject "A friendly reminder": "Hello {r.gymnast}, our records show a fees of {r.fees}. Questions? Just reply."
      let ok = request approval of m from owner timeout 6 hours else skip
      send ok
    }
  }
}

