procedure SalonBookedFollowUp {
  about "Follow up with clients marked booked"
  policy SalonPolicy
  sheet Clients "Clients" { name: Text, phone: Phone, last_visit: Date, status: Text, tab: Money, color_formula: Text private }
  trigger every day at 11:00

  let all = fetch Clients
  let recent = filter all where status == "booked" and days_between(last_visit, today()) <= 3 and days_between(last_visit, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no booked clients"
  }
  notify owner "Booked clients to follow up: {n}"
  let msgs = draft each r in recent up to 40 sms to r.phone: "Hi {r.name}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
  for each r in recent up to 40 {
    update r set status = "contacted"
  }
}

