procedure FencingWinBack {
  about "Nudge fencers whose bout was long ago"
  policy FencingPolicy
  sheet Fencers "Fencers" { fencer: Text, email: Email, bout_at: DateTime, status: Text, dues: Money, injury_notes: Text private }
  trigger every friday at 09:00

  let all = fetch Fencers
  let old = filter all where days_between(bout_at, today()) >= 90 and status != "left"
  let oldest = sort old by bout_at first 20
  for each r in oldest up to 20 {
    let m = draft email to r.email subject "We miss you": "Hi {r.fencer default 'there'}, it's been a while! We'd love to see you again at the club."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
  notify owner "Please update our bookkeeper yourself."
}

