policy:
policy CatcafeStockPolicy {
  allow read Treats(treat, bags, minimum, reorder_qty, vendor, unit_cost)
  allow supplier Treats.vendor
  limit order $150 per action
  limit order $450 per day
}

program:
procedure CatcafeReorder {
  about "Reorder cat treats below their minimum"
  policy CatcafeStockPolicy
  sheet Treats "Treats" { treat: Text, bags: Number, minimum: Number, reorder_qty: Number, vendor: Text, unit_cost: Money }
  trigger every friday at 09:00

  let all = fetch Treats
  let low = filter all where bags < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $150.00 {
      notify owner "Reorder of {i.treat} would cost {cost}, over the $150 limit."
      skip
    }
    order "{i.reorder_qty} x {i.treat}" from i.vendor cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.treat}"
  }
}

