procedure RestaurantOutreachCampaign {
  about "On request, contact recent cancelled guests"
  policy RestaurantPolicy
  sheet Bookings "Bookings" { guest: Text, phone: Phone, at: DateTime, status: Text, deposit: Money, allergies: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

