procedure LandscapingAcceptedFollowUp {
  about "Follow up with customers marked accepted"
  policy LandscapingPolicy
  sheet Quotes "Quotes" { customer: Text, email: Email, sent_on: Date, status: Text, amount: Money, gate_code: Text private }
  trigger every day at 08:30

  let all = fetch Quotes
  let recent = filter all where status == "accepted" and days_between(sent_on, today()) <= 2 and days_between(sent_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no accepted customers"
  }
  notify owner "Accepted customers to follow up: {n}"
  let msgs = draft each r in recent up to 30 email to r.email subject "Let's find a new time": "Hi {r.customer default 'there'}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
  for each r in recent up to 30 {
    update r set status = "followed-up"
  }
