procedure BakeryLateBalance {
  about "Remind late customers; escalate very late ones"
  policy BakeryPolicy
  sheet CakeOrders "CakeOrders" { customer: Text, email: Email, pickup: Date, status: Text, price: Money, address: Text private }
  trigger every day at 08:30

  let all = fetch CakeOrders
  let late = filter all where price > $0.00 and days_between(pickup, today()) > 3
  for each r in late up to 30 {
    if days_between(r.pickup, today()) > 14 {
      notify owner "{r.customer} is very late ({r.price}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.customer default 'there'}, our records show a price of {r.price}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
  notify owner "Please update the office manager yourself."
}

