policy:
policy FilmlabStockPolicy {
  allow read Chemicals(chemical, litres, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Chemicals.supplier
  limit order $150 per action
  limit order $750 per day
}

program:
procedure FilmlabReorder {
  about "Reorder chemicals below their minimum"
  policy FilmlabStockPolicy
  sheet Chemicals "Chemicals" { chemical: Text, litres: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 08:00

  let all = fetch Chemicals
  let low = filter all where litres < minimum
  for each i in low up to 5 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $150.00 {
      notify owner "Reorder of {i.chemical} would cost {cost}, over the $150 limit."
      skip
    }
    order "{i.reorder_qty} x {i.chemical}" from i.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.chemical}"
  }
}

