procedure CostumeOverdueFollowUp {
  about "Follow up with renters marked overdue"
  policy CostumePolicy
  sheet Rentals "Rentals" { renter: Text, phone: Phone, due_back: Date, status: Text, deposit: Money, id_number: Text private }
  trigger every day at 10:00

  let all = fetch Rentals
  let recent = filter all where status == "overdue" and days_between(due_back, today()) <= 3 and days_between(due_back, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no overdue renters"
  }
  notify owner "Overdue renters to follow up: {n}"
  let msgs = draft each r in recent up to 40 sms to r.phone: "Hi {r.renter}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 6 hours else stop "batch not approved"
  send ok
  for each r in recent up to 40 {
    update r set status = "contacted"
  }
}

