  sheet PullList "PullList" { reader: Text, email: Email, arrives_on: Date, status: Text, owed: Money, home_address: Text private }
  trigger every thursday at 16:00

  let all = fetch PullList
  let old = filter all where days_between(arrives_on, today()) >= 42 and status != "cancelled"
  let oldest = sort old by arrives_on first 15
  for each r in oldest up to 15 {
    let m = draft email to r.email subject "We miss you": "Hi {r.reader}, it's been a while! We'd love to see you again at the shop."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

