procedure ComicsLateBalance {
  about "Remind late readers; escalate very late ones"
  policy ComicsPolicy
  sheet PullList "PullList" { reader: Text, email: Email, arrives_on: Date, status: Text, owed: Money, home_address: Text private }
  trigger every day at 08:30

  let all = fetch PullList
  let late = filter all where owed > $0.00 and days_between(arrives_on, today()) > 5
  for each r in late up to 20 {
    if days_between(r.arrives_on, today()) > 30 {
      notify owner "{r.reader} is very late ({r.owed}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.reader}, our records show a owed of {r.owed}. Questions? Just reply."
      let ok = request approval of m from owner timeout 6 hours else skip
      send ok
    }
  }
}

