  let msgs = draft each r in targets up to 100 email to r.email subject "We'd love to see you": "Hi {r.customer default 'there'}, come back to the bakery! Use code RETURN20 on your next visit."
  let ok = request batch approval of msgs from owner timeout 6 hours else stop "batch not approved"
