procedure GymFrozenFollowUp {
  about "Follow up with members marked frozen"
  policy GymPolicy
  sheet Members "Members" { name: Text, email: Email, renews_on: Date, status: Text, dues: Money, health_notes: Text private }
  trigger every friday at 09:00

  let all = fetch Members
  let recent = filter all where status == "frozen" and days_between(renews_on, today()) <= 3 and days_between(renews_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no frozen members"
  }
  notify owner "Frozen members to follow up: {n}"
  let msgs = draft each r in recent up to 30 email to r.email subject "Let's find a new time": "Hi {r.name}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok
  for each r in recent up to 30 {
    update r set status = "contacted"
  }
}

