policy:
policy SignsStockPolicy {
  allow read Vinyl(color, rolls, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Vinyl.supplier
  limit order $200 per action
  limit order $800 per day
}

program:
procedure SignsReorder {
  about "Reorder vinyl below their minimum"
  policy SignsStockPolicy
  sheet Vinyl "Vinyl" { color: Text, rolls: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every friday at 18:00

  let all = fetch Vinyl
  let low = filter all where rolls < minimum
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $200.00 {
      notify owner "Reorder of {i.color} would cost {cost}, over the $200 limit."
      skip
    }
    order "{i.reorder_qty} x {i.color}" from i.supplier cost cost, ask owner first timeout 6 hours else skip
    log "ordered {i.color}"
  }
}

