  policy PetgroomerPolicy
  sheet Grooms "Grooms" { owner: Text, phone: Phone, appointment: DateTime, status: Text, price: Money, behavior_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Grooms
  let targets = filter all where status == "cancelled" and days_between(appointment, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft sms to r.phone: "Hi {r.owner default 'there'}, come back to the salon! Use code WELCOME10 on your next visit."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

