procedure AutorepairPickedUpFollowUp {
  about "Follow up with customers marked picked-up"
  policy AutorepairPolicy
  sheet Jobs "Jobs" { owner_name: Text, phone: Phone, promised: DateTime, status: Text, estimate: Money, vin: Text private }
  trigger every wednesday at 08:00

  let all = fetch Jobs
  let recent = filter all where status == "picked-up" and days_between(promised, today()) <= 3 and days_between(promised, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no picked-up customers"
  }
  notify owner "Picked-up customers to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft sms to r.phone: "Hi {r.owner_name default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
    update r set status = "contacted"
  }
}

