procedure YogaLateBalance {
  about "Remind late students; escalate very late ones"
  policy YogaPolicy
  sheet Passes "Passes" { name: Text, email: Email, expires_on: Date, status: Text, credit: Money, injury_notes: Text private }
  trigger every day at 11:00

  let all = fetch Passes
  let late = filter all where credit > $0.00 and days_between(expires_on, today()) > 5
  for each r in late up to 40 {
    if days_between(r.expires_on, today()) > 14 {
      notify owner "{r.name} is very late ({r.credit}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.name default 'there'}, our records show a credit of {r.credit}. Questions? Just reply."
      let ok = request approval of m from owner timeout 6 hours else skip
      send ok
    }
  }
}

