policy:
policy BikeshopStockPolicy {
  allow read Parts(part, qty, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Parts.supplier
  limit order $100 per action
  limit order $300 per day
}

program:
procedure BikeshopReorder {
  about "Reorder parts below their minimum"
  policy BikeshopStockPolicy
  sheet Parts "Parts" { part: Text, qty: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every wednesday at 11:00

  let all = fetch Parts
  let low = filter all where qty < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $100.00 {
      notify owner "Reorder of {i.part} would cost {cost}, over the $100 limit."
      skip
    }
    order "{i.reorder_qty} x {i.part}" from i.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.part}"
  }
}

