procedure NotaryConfirmNewSigning {
  about "Confirm a new signing and add it to the calendar"
  policy NotaryPolicy
  sheet Signings "Signings" { signer: Text, email: Email, signing_at: DateTime, status: Text, fee: Money, id_number: Text private }
  calendar Desks "Desks"
  trigger when new row r in Signings

  if r.signing_at < now() + 24 hours {
    notify owner "Short-notice signing for {r.signer} at {r.signing_at}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft email to r.email subject "Confirmed": "Hi {r.signer default 'there'}, your signing with the office is confirmed for {r.signing_at}."
  let ok = request approval of m from owner timeout 1 day else stop "confirmation not approved"
  send ok
  let ev = book Desks { title: "{r.signer}", at: r.signing_at, length: 90 minutes }
  update r set status = "confirmed"
}

