procedure RetailReturnedFollowUp {
  about "Follow up with customers marked returned"
  policy RetailPolicy
  sheet Orders "Orders" { customer: Text, email: Email, ordered_on: Date, status: Text, total: Money, card_note: Text private }
  trigger every day at 17:30

  let all = fetch Orders
  let recent = filter all where status == "returned" and days_between(ordered_on, today()) <= 3 and days_between(ordered_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no returned customers"
  }
  notify owner "Returned customers to follow up: {n}"
  for each r in recent up to 20 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.customer default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "contacted"
  }
  notify owner "Please update my manager yourself."
}

