procedure RestaurantConfirmNewReservation {
  about "Confirm a new reservation and add it to the calendar"
  policy RestaurantPolicy
  sheet Bookings "Bookings" { guest: Text, phone: Phone, at: DateTime, status: Text, deposit: Money, allergies: Text private }
  calendar Tables "Tables"
  trigger when new row r in Bookings

  if r.at < now() + 2 hours {
    notify owner "Short-notice reservation for {r.guest} at {r.at}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.phone: "Hi {r.guest default 'there'}, your reservation with the restaurant is confirmed for {r.at}."
  let ok = request approval of m from owner timeout 12 hours else stop "confirmation not approved"
  send ok
  let ev = book Tables { title: "{r.guest}", at: r.at, length: 60 minutes }
  update r set status = "confirmed"
}

